package in.aicon.pocket;
import android.content.ContentValues;import android.database.Cursor;import android.database.sqlite.SQLiteDatabase;import java.util.*;import org.json.*;

/** Account-private pending conflict snapshots, never uploaded or logged. Choosing a
 * version must happen after the caller has displayed its contents for that ledger.
 */
public final class ConflictReviewStore {
 private final SQLiteDatabase db;
 public static final class Review {public final String id,key;public final long revision;public final SyncModel.Conflict conflict;final Map<String,List<SyncModel.Record>> candidates;Review(String id,String key,long revision,SyncModel.Conflict conflict,Map<String,List<SyncModel.Record>> candidates){this.id=id;this.key=key;this.revision=revision;this.conflict=conflict;this.candidates=candidates;}}
 public ConflictReviewStore(SQLiteDatabase db,String subject){if(!new java.io.File(db.getPath()).getName().equals(AccountScope.databaseFor(subject)))throw new IllegalArgumentException("Conflict review requires matching account ledger");this.db=db;db.execSQL("CREATE TABLE IF NOT EXISTS conflict_review(singleton INTEGER PRIMARY KEY CHECK(singleton=1),uuid TEXT NOT NULL,revision INTEGER NOT NULL,versions TEXT NOT NULL,context TEXT NOT NULL DEFAULT '{}',token TEXT NOT NULL DEFAULT '')");Set<String> columns=new HashSet<>();try(Cursor c=db.rawQuery("PRAGMA table_info(conflict_review)",null)){while(c.moveToNext())columns.add(c.getString(1));}if(!columns.contains("token"))db.execSQL("ALTER TABLE conflict_review ADD COLUMN token TEXT NOT NULL DEFAULT ''");if(!columns.contains("context"))db.execSQL("ALTER TABLE conflict_review ADD COLUMN context TEXT NOT NULL DEFAULT '{}'");}
 public void save(long revision,SyncModel.Conflict conflict,Map<String,List<SyncModel.Record>> candidates)throws Exception{if(!db.inTransaction())throw new IllegalStateException("Review state must share a transaction");if(revision<0)throw new IllegalArgumentException("Invalid ledger revision");JSONArray versions=new JSONArray();for(SyncModel.Record candidate:conflict.versions)versions.put(new JSONObject(SyncJson.record(candidate)));String json=versions.toString();if(json.length()>2*1024*1024)throw new IllegalArgumentException("Conflict too large for inline review");ContentValues v=new ContentValues();v.put("singleton",1);v.put("token",UUID.randomUUID().toString());v.put("uuid",conflict.local.id);v.put("revision",revision);v.put("versions",json);JSONObject context=new JSONObject();for(Map.Entry<String,List<SyncModel.Record>> entry:candidates.entrySet()){Identifiers.uuid(entry.getKey());JSONArray records=new JSONArray();for(SyncModel.Record r:entry.getValue()){if(!r.id.equals(entry.getKey()))throw new IllegalArgumentException("Candidate ID mismatch");records.put(new JSONObject(SyncJson.record(r)));}context.put(entry.getKey(),records);}String staged=context.toString();if(staged.length()>8*1024*1024)throw new IllegalArgumentException("Review context exceeds limit");v.put("context",staged);if(db.insertWithOnConflict("conflict_review",null,v,SQLiteDatabase.CONFLICT_REPLACE)==-1)throw new IllegalStateException("Could not retain conflict review");}
 public Review current()throws Exception{try(Cursor c=db.rawQuery("SELECT uuid,revision,versions,context,token FROM conflict_review WHERE singleton=1",null)){if(!c.moveToFirst())return null;String id=c.getString(0);Identifiers.uuid(id);JSONArray a=new JSONArray(c.getString(2));if(a.length()<2||a.length()>256)throw new IllegalArgumentException("Invalid review versions");List<SyncModel.Record> versions=new ArrayList<>();for(int n=0;n<a.length();n++){SyncModel.Record record=SyncJson.parseRecord(a.getJSONObject(n).toString());if(!id.equals(record.id))throw new IllegalArgumentException("Conflict ID differs");versions.add(record);}JSONObject context=new JSONObject(c.getString(3));Map<String,List<SyncModel.Record>> candidates=new TreeMap<>();Iterator<String> ids=context.keys();while(ids.hasNext()){String key=ids.next();Identifiers.uuid(key);JSONArray records=context.getJSONArray(key);List<SyncModel.Record> list=new ArrayList<>();for(int n=0;n<records.length();n++){SyncModel.Record r=SyncJson.parseRecord(records.getJSONObject(n).toString());if(!r.id.equals(key))throw new IllegalArgumentException("Candidate ID mismatch");list.add(r);}candidates.put(key,list);}if(candidates.isEmpty())throw new IllegalStateException("Older review needs a fresh sync");String key=c.getString(4);Identifiers.uuid(key);return new Review(id,key,c.getLong(1),new SyncModel.Conflict(versions),candidates);}}
 public void clear(){if(!db.inTransaction())throw new IllegalStateException("Clear review with its resolution");db.delete("conflict_review",null,null);}
}
